import React, { useState, useEffect } from 'react';
import API from "../api/axios";
import { useNavigate } from "react-router-dom";
import { Mail, Lock, ArrowRight, X, ArrowLeft, ShieldCheck, Zap, CheckCircle2, Save } from 'lucide-react';

const EntryCard = ({ isOpen, onClose }) => {
  const navigate = useNavigate();

  const [isFlipped, setIsFlipped] = useState(false);
  const [loginView, setLoginView] = useState('login');

  // LOGIN
  const [loginEmail, setLoginEmail] = useState("");
  const [loginPassword, setLoginPassword] = useState("");
  const [loginError, setLoginError] = useState("");

  // SIGNUP FLOW
  const [signupStep, setSignupStep] = useState(1);
  const [signupOtpSent, setSignupOtpSent] = useState(false);

  const [signupEmail, setSignupEmail] = useState("");
  const [signupOtp, setSignupOtp] = useState("");
  const [signupName, setSignupName] = useState("");
  const [signupPhone, setSignupPhone] = useState("");
  const [signupAddress, setSignupAddress] = useState("");
  const [signupPassword, setSignupPassword] = useState("");
  const [signupError, setSignupError] = useState("");

  useEffect(() => {
    if (!isOpen) {
      setIsFlipped(false);
      setLoginView('login');
      setSignupStep(1);
      setSignupOtpSent(false);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  // 🔥 LOGIN
  const handleLogin = async () => {
    if (!loginEmail || !loginPassword) {
      setLoginError("Please fill email and password");
      return;
    }

    try {
      const res = await API.post("/auth/login", {
        email: loginEmail,
        password: loginPassword,
      });

      localStorage.setItem("token", res.data.token);
      navigate("/dashboard");

    } catch {
      setLoginError("Invalid email or password");
    }
  };

  // 🔥 SEND OTP
  const handleSendOtp = async () => {
    if (!signupEmail) {
      setSignupError("Enter email first");
      return;
    }

    try {
      await API.post("/auth/send-otp", { email: signupEmail });
      setSignupOtpSent(true);
      setSignupError("");
    } catch {
      setSignupError("Failed to send OTP");
    }
  };

  // 🔥 VERIFY OTP
  const handleVerifyOtp = async () => {
    if (!signupOtp) {
      setSignupError("Enter OTP");
      return;
    }

    try {
      await API.post("/auth/verify-otp", {
        email: signupEmail,
        otp: signupOtp,
      });

      setSignupStep(2);
      setSignupError("");
    } catch {
      setSignupError("Invalid OTP");
    }
  };

  // 🔥 REGISTER
  const handleSignup = async () => {
    if (!signupName || !signupPhone || !signupPassword) {
      setSignupError("Fill all fields");
      return;
    }

    try {
      await API.post("/auth/register", {
        fullName: signupName,
        email: signupEmail,
        password: signupPassword,
        phone: signupPhone,
        role: "CITIZEN",
      });

      alert("Registered successfully ✅");
      setIsFlipped(false);

    } catch {
      setSignupError("Signup failed");
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#47510B]/60 backdrop-blur-md p-4">

      <div className="flip-container w-full max-w-[400px] h-[600px]">
        <div className={`flip-inner ${isFlipped ? 'is-flipped' : ''}`}>

          {/* LOGIN */}
          <div className="flip-front bg-[#FDFAD8] p-8 flex flex-col justify-between">

            <button onClick={onClose}><X /></button>

            <div>
              <input
                type="email"
                placeholder="EMAIL"
                value={loginEmail}
                onChange={(e) => setLoginEmail(e.target.value)}
                className="w-full p-3 border mb-3"
              />

              <input
                type="password"
                placeholder="PASSWORD"
                value={loginPassword}
                onChange={(e) => setLoginPassword(e.target.value)}
                className="w-full p-3 border mb-2"
              />

              {loginError && <p className="text-red-500 text-sm">{loginError}</p>}

              <button onClick={handleLogin} className="w-full bg-black text-white p-3 mt-3">
                Login
              </button>
            </div>

            <button onClick={() => setIsFlipped(true)}>Go Signup</button>
          </div>

          {/* SIGNUP */}
          <div className="flip-back bg-[#FFB6A9] p-6 flex flex-col">

            <button onClick={() => setIsFlipped(false)}>
              <ArrowLeft />
            </button>

            {signupStep === 1 ? (
              <>
                <input
                  type="email"
                  placeholder="EMAIL"
                  value={signupEmail}
                  onChange={(e) => setSignupEmail(e.target.value)}
                  className="p-3 border mb-2"
                />

                <button onClick={handleSendOtp} className="bg-black text-white p-2">
                  Send OTP
                </button>

                {signupOtpSent && (
                  <>
                    <input
                      type="text"
                      placeholder="OTP"
                      value={signupOtp}
                      onChange={(e) => setSignupOtp(e.target.value)}
                      className="p-3 border mt-3"
                    />

                    <button onClick={handleVerifyOtp} className="bg-green-600 text-white p-2 mt-2">
                      Verify OTP
                    </button>
                  </>
                )}
              </>
            ) : (
              <>
                <input
                  placeholder="Full Name"
                  value={signupName}
                  onChange={(e) => setSignupName(e.target.value)}
                  className="p-2 border mb-2"
                />

                <input
                  placeholder="Phone"
                  value={signupPhone}
                  onChange={(e) => setSignupPhone(e.target.value)}
                  className="p-2 border mb-2"
                />

                <input
                  placeholder="Password"
                  type="password"
                  value={signupPassword}
                  onChange={(e) => setSignupPassword(e.target.value)}
                  className="p-2 border mb-2"
                />

                <button onClick={handleSignup} className="bg-red-600 text-white p-3">
                  Register
                </button>
              </>
            )}

            {signupError && <p className="text-red-500 text-sm mt-2">{signupError}</p>}
          </div>

        </div>
      </div>
    </div>
  );
};

export default EntryCard;
